insert into public.content (id, kind, published, data) values ('mur-led', 'products', true, '{"id":"mur-led","kind":"products","title":"Mur LED modulaire","description":"Exemple de fiche, à remplacer par le matériel EVENTHEMES. Mur d’images assemblable pour scène, conférence ou salon : taille, pas de pixel et luminosité définis selon le lieu et la distance de vision.","published":true,"category":"cat-image","reference":"DEMO-LED-01","subcategory":"cat-image-led","image":"https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1400&q=85","pricing":"request","variants":[{"name":"Intérieur","price":null},{"name":"Extérieur","price":null}],"demo":true,"available":true,"translations":{"en":{"title":"Modular LED wall","description":"Example listing, to be replaced with EVENTHEMES equipment. Video wall assembled for a stage, conference or trade show: size, pixel pitch and brightness chosen according to the venue and the viewing distance.","variants":"Indoor\nOutdoor"}}}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('line-array', 'products', true, '{"id":"line-array","kind":"products","title":"Système de sonorisation line array","description":"Exemple de fiche, à remplacer par le matériel EVENTHEMES. Diffusion suspendue ou posée pour couvrir un large public ; configuration calculée selon la jauge et l’acoustique du lieu.","published":true,"category":"cat-son","reference":"DEMO-SON-01","subcategory":"cat-son-diffusion","image":"https://images.unsplash.com/photo-1524368535928-5b5e00ddc76b?auto=format&fit=crop&w=1400&q=85","pricing":"request","demo":true,"available":true,"translations":{"en":{"title":"Line array sound system","description":"Example listing, to be replaced with EVENTHEMES equipment. Flown or ground-stacked system to cover a large audience; configuration calculated according to the capacity and acoustics of the venue."}}}'::jsonb) on conflict (id) do nothing;
