insert into public.content (id, kind, published, data) values ('scene', 'products', true, '{"id":"scene","kind":"products","title":"Scène modulaire","description":"Exemple de fiche, à remplacer par le matériel EVENTHEMES. Praticables assemblables pour composer une scène ou un podium à la hauteur et aux dimensions de votre événement.","published":true,"category":"cat-scenes","color":"Noir","reference":"DEMO-SCN-01","swatch":"#08090b","image":"https://images.unsplash.com/photo-1504680177321-2e6a879aac86?auto=format&fit=crop&w=2000&q=85","pricing":"request","demo":true,"available":true,"translations":{"en":{"title":"Modular stage","description":"Example listing, to be replaced with EVENTHEMES equipment. Stage decks assembled into a stage or riser at the height and size your event needs.","color":"Black"}}}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('fumee', 'products', true, '{"id":"fumee","kind":"products","title":"Machine à fumée","description":"Exemple de fiche, à remplacer par le matériel EVENTHEMES. Brouillard ou fumée lourde pour révéler les faisceaux lumineux et créer l’atmosphère.","published":true,"category":"cat-effets","reference":"DEMO-EFX-01","subcategory":"cat-effets-fumee","image":"https://images.unsplash.com/photo-1493225457124-a3eb161ffa5f?auto=format&fit=crop&w=1400&q=85","pricing":"request","demo":true,"available":true,"translations":{"en":{"title":"Smoke machine","description":"Example listing, to be replaced with EVENTHEMES equipment. Haze or low fog to reveal light beams and create atmosphere."}}}'::jsonb) on conflict (id) do nothing;
