insert into public.content (id, kind, published, data) values ('cities-page', 'pages', true, '{"id":"cities-page","kind":"pages","title":"Nos zones\nd’intervention.","description":"Les villes où notre équipe intervient pour vos événements : scène, structures, écrans LED, son, lumière et régie technique.","published":true,"demo":false,"available":true,"translations":{"en":{"title":"Our service\nareas.","description":"The cities where our team works on your events: stage, structures, LED screens, sound, lighting and technical control."}}}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('casablanca', 'cities', false, '{"id":"casablanca","kind":"cities","title":"Casablanca","description":"Capitale économique du Maroc, Casablanca accueille conventions, salons, lancements de produits et soirées d’entreprise. Pour chacun de ces formats, notre équipe conçoit la technique adaptée : scène, structures, écrans LED, sonorisation, éclairage et régie.","published":false,"demo":false,"available":true,"translations":{"en":{"description":"Morocco’s economic capital, Casablanca hosts conventions, trade shows, product launches and corporate parties. For each of these formats, our team designs the right technical set-up: stage, structures, LED screens, sound, lighting and control."}}}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('rabat', 'cities', false, '{"id":"rabat","kind":"cities","title":"Rabat","description":"À Rabat, conférences, cérémonies et événements institutionnels demandent une technique précise et discrète : sonorisation des interventions, écrans, éclairage et régie, préparés avec méthode.","published":false,"demo":false,"available":true,"translations":{"en":{"description":"In Rabat, conferences, ceremonies and institutional events call for precise, discreet technical production: speech reinforcement, screens, lighting and control, prepared with method."}}}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('marrakech', 'cities', false, '{"id":"marrakech","kind":"cities","title":"Marrakech","description":"Galas, soirées privées et séminaires à Marrakech : nous composons la scène, la lumière, l’image et le son de votre événement, en intérieur comme en plein air.","published":false,"demo":false,"available":true,"translations":{"en":{"description":"Galas, private parties and seminars in Marrakech: we put together the stage, lighting, video and sound of your event, indoors or in the open air."}}}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('tanger', 'cities', false, '{"id":"tanger","kind":"cities","title":"Tanger","description":"À Tanger, nous accompagnons vos événements d’entreprise, concerts et soirées : étude technique du lieu, installation, exploitation et démontage.","published":false,"demo":false,"available":true,"translations":{"en":{"title":"Tangier","description":"In Tangier, we support your corporate events, concerts and parties: technical survey of the venue, installation, operation and get-out."}}}'::jsonb) on conflict (id) do nothing;
insert into public.content (id, kind, published, data) values ('agadir', 'cities', false, '{"id":"agadir","kind":"cities","title":"Agadir","description":"Séminaires, soirées et événements en plein air à Agadir : scène, structures, sonorisation et éclairage dimensionnés pour votre lieu et votre public.","published":false,"demo":false,"available":true,"translations":{"en":{"description":"Seminars, parties and open-air events in Agadir: stage, structures, sound and lighting sized for your venue and your audience."}}}'::jsonb) on conflict (id) do nothing;
